def estimate(points, x):
    """Piecewise linear interpolation.

    * ``points`` is a list of (x, y) sorted by x.
    * If ``x`` is outside the domain, the nearest endpoint y is returned.
    * For a single sample, its y is always returned.
    """
    if not points:
        raise ValueError("no points for interpolation")
    # Single sample case
    if len(points) == 1:
        return points[0][1]
    # Clamp to endpoints
    if x <= points[0][0]:
        return points[0][1]
    if x >= points[-1][0]:
        return points[-1][1]
    # Find interval
    for i in range(1, len(points)):
        left_x, left_y = points[i - 1]
        right_x, right_y = points[i]
        if x <= right_x:
            # Linear interpolation
            dx = right_x - left_x
            if dx == 0:
                # Should not happen due to duplicate check, but guard anyway
                return left_y
            t = (x - left_x) / dx
            return left_y + t * (right_y - left_y)
    # Fallback (should not reach here)
    return points[-1][1]

