def prepare(points):
    """Validate and prepare sample points.

    * ``points`` must be an iterable of (x, y) pairs.
    * Duplicate x values raise ``ValueError``.
    * Empty input raises ``ValueError``.
    * Returns a list of (x, y) sorted by x.
    """
    if not points:
        raise ValueError("empty samples")
    seen = {}
    for x, y in points:
        # Ensure x is a finite number
        if not isinstance(x, (int, float)):
            raise ValueError("non‑numeric x coordinate")
        if x in seen:
            raise ValueError("duplicate coordinate")
        seen[x] = y
    if not seen:
        raise ValueError("empty samples")
    # Return sorted by x
    return sorted(seen.items(), key=lambda item: item[0])

